// Some portions generated by Claude

/** Where an arrow key moves on the canvas. */
export type ArrowDirection = "left" | "right" | "up" | "down";

/** The arrow keys, by `KeyboardEvent.key`. */
export const ARROW_KEYS: Readonly<Record<string, ArrowDirection>> = {
  ArrowLeft: "left",
  ArrowRight: "right",
  ArrowUp: "up",
  ArrowDown: "down",
};

const STEP: Record<ArrowDirection, [number, number]> = { left: [-1, 0], right: [1, 0], up: [0, -1], down: [0, 1] };

/**
 * The node an arrow key moves to from `fromId`: the nearest one ahead in that direction (within about 56° of it), a
 * step aside counting twice as much as a step ahead, so a node in line wins over a nearer one off to the side. Null
 * when no node lies that way.
 */
export function nodeInDirection(
  nodes: readonly { id: string; x?: number; y?: number }[],
  fromId: string,
  direction: ArrowDirection,
): string | null {
  const from = nodes.find((node) => node.id === fromId);
  if (from?.x === undefined || from.y === undefined) return null;
  const [dx, dy] = STEP[direction];
  let best: string | null = null;
  let bestScore = Infinity;
  for (const node of nodes) {
    if (node.id === fromId || node.x === undefined || node.y === undefined) continue;
    const vx = node.x - from.x, vy = node.y - from.y;
    const ahead = vx * dx + vy * dy;
    const aside = Math.abs(vx * dy - vy * dx);
    if (ahead <= 0 || aside > ahead * 1.5) continue;
    const score = ahead + 2 * aside;
    if (score < bestScore) {
      bestScore = score;
      best = node.id;
    }
  }
  return best;
}
